// Parses a FROM JOIN type, if present.
fn parse_from_join(&mut self) -> Result<Option<ast::JoinType>> {
    Ok(match self.next_if_keyword() {
        Some(Keyword::Join) => Some(ast::JoinType::Inner),
        Some(Keyword::Cross) => {
            self.expect(Token::Keyword(Keyword::Join))?;
            Some(ast::JoinType::Cross)
        }
        Some(Keyword::Inner) => {
            self.expect(Token::Keyword(Keyword::Join))?;
            Some(ast::JoinType::Inner)
        }
        Some(Keyword::Left) => {
            self.expect(Token::Keyword(Keyword::Join))?;
            Some(ast::JoinType::Left)
        }
        Some(Keyword::Right) => {
            self.expect(Token::Keyword(Keyword::Join))?;
            Some(ast::JoinType::Right)
        }
        Some(Keyword::Outer) => {
            self.expect(Token::Keyword(Keyword::Join))?;
            return Err(errinput!("unexpected OUTER keyword"));
        }
        _ => None,
    })
}
